import type { Metadata } from "next";
import {
  COMPANY,
  DEFAULT_LOCALE,
  LOCALES,
  LOCALE_TAGS,
  SITE_URL,
  absoluteUrl,
  landingPath,
  path,
  type Locale,
  type RouteKey,
} from "@/content/site";
import { getDictionary } from "@/content/locales";
import { LANDING_LOCALES, type Landing } from "@/content/landings";

type SeoKey = keyof ReturnType<typeof getDictionary>["seo"];

/**
 * The social card generated by `src/app/opengraph-image.tsx`, republished as a
 * real .png by `scripts/postbuild.mjs` so GitHub Pages serves the right
 * content type.
 */
const OG_IMAGE = {
  url: `${SITE_URL}/og.png`,
  width: 1200,
  height: 630,
  alt: `${COMPANY.name} — ${COMPANY.expansion}`,
};

/** Open Graph locale codes, which differ slightly from BCP-47 tags. */
const OG_LOCALES: Record<Locale, string> = {
  uk: "uk_UA",
  en: "en_US",
  ru: "ru_RU",
};

interface PageSeo {
  title: string;
  description: string;
  keywords: string[];
}

/** Shared shape: canonical, hreflang alternates, Open Graph and Twitter. */
function compose(
  locale: Locale,
  seo: PageSeo,
  url: string,
  alternates: { locale: Locale; url: string }[],
): Metadata {
  const languages: Record<string, string> = {};
  for (const alt of alternates) languages[LOCALE_TAGS[alt.locale]] = alt.url;
  const fallback =
    alternates.find((alt) => alt.locale === DEFAULT_LOCALE) ?? alternates[0];
  if (fallback) languages["x-default"] = fallback.url;

  return {
    title: seo.title,
    description: seo.description,
    keywords: seo.keywords,
    alternates: { canonical: url, languages },
    openGraph: {
      type: "website",
      siteName: COMPANY.name,
      title: seo.title,
      description: seo.description,
      url,
      locale: OG_LOCALES[locale],
      alternateLocale: alternates
        .filter((alt) => alt.locale !== locale)
        .map((alt) => OG_LOCALES[alt.locale]),
      images: [OG_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title: seo.title,
      description: seo.description,
      images: [OG_IMAGE.url],
    },
  };
}

/** Metadata for a localized top-level page. */
export function buildMetadata(
  locale: Locale,
  route: RouteKey,
  seoKey: SeoKey = route as SeoKey,
): Metadata {
  const dict = getDictionary(locale);
  return compose(
    locale,
    dict.seo[seoKey],
    absoluteUrl(path(locale, route)),
    LOCALES.map((alt) => ({ locale: alt, url: absoluteUrl(path(alt, route)) })),
  );
}

/** Metadata for a search landing; alternates cover only its own locales. */
export function buildLandingMetadata(
  locale: Locale,
  slug: string,
  landing: Landing,
): Metadata {
  return compose(
    locale,
    landing.seo,
    absoluteUrl(landingPath(locale, slug)),
    LANDING_LOCALES.map((alt) => ({
      locale: alt,
      url: absoluteUrl(landingPath(alt, slug)),
    })),
  );
}
